10	
11	#include "engine/endpoint_matcher.h"
12	#include <algorithm>
13	#include "common/hixl_checker.h"
14	#include "common/hixl_log.h"
15	#include "engine/client_handler_factory.h"
16	
17	namespace hixl {
18	namespace {
19	constexpr uint32_t kMaxUbCsClientNum = 4U;
20	
21	enum class MatchRuleType {
22	  GROUP,
23	  SINGLE,
24	};
25	
26	struct MatchRule {
27	  MatchRuleType rule_type;
28	  HandlerCreateArgs::HandlerType handler_type;
29	  const char *protocol;
30	  const char *placement;
31	  CommType type;
32	  const char *reason;
33	};
34	
35	constexpr MatchRule kCrossInstanceRules[] = {
36	    {MatchRuleType::SINGLE, HandlerCreateArgs::HandlerType::DIRECT, kProtocolUboe, kPlacementDevice,
37	     CommType::COMM_TYPE_UBOE, "cross-instance prefers device uboe"},
38	    {MatchRuleType::SINGLE, HandlerCreateArgs::HandlerType::DIRECT, kProtocolUbRtp, kPlacementDevice,
39	     CommType::COMM_TYPE_UBG, "cross-instance falls back to device ub_rtp"},
40	    {MatchRuleType::SINGLE, HandlerCreateArgs::HandlerType::DIRECT, kProtocolRoce, kPlacementDevice,
41	     CommType::COMM_TYPE_ROCE, "cross-instance falls back to device roce"},
42	    {MatchRuleType::SINGLE, HandlerCreateArgs::HandlerType::DIRECT, kProtocolRoce, kPlacementHost,
43	     CommType::COMM_TYPE_ROCE, "cross-instance falls back to host roce"},
44	};
45	
46	constexpr MatchRule kSameInstanceRules[] = {
47	    {MatchRuleType::GROUP, HandlerCreateArgs::HandlerType::UB, nullptr, nullptr, CommType::COMM_TYPE_UB_D2D,
48	     "same-instance prefers ub group"},
49	    {MatchRuleType::SINGLE, HandlerCreateArgs::HandlerType::DIRECT, kProtocolHccs, kPlacementDevice,
50	     CommType::COMM_TYPE_HCCS, "same-instance falls back to device hccs"},
51	    {MatchRuleType::SINGLE, HandlerCreateArgs::HandlerType::DIRECT, kProtocolUboe, kPlacementDevice,
52	     CommType::COMM_TYPE_UBOE, "same-instance falls back to device uboe"},
53	    {MatchRuleType::SINGLE, HandlerCreateArgs::HandlerType::DIRECT, kProtocolUbRtp, kPlacementDevice,
54	     CommType::COMM_TYPE_UBG, "same-instance falls back to device ub_rtp"},
55	    {MatchRuleType::SINGLE, HandlerCreateArgs::HandlerType::DIRECT, kProtocolRoce, kPlacementDevice,
56	     CommType::COMM_TYPE_ROCE, "same-instance falls back to device roce"},
57	    {MatchRuleType::SINGLE, HandlerCreateArgs::HandlerType::DIRECT, kProtocolRoce, kPlacementHost,
58	     CommType::COMM_TYPE_ROCE, "same-instance falls back to host roce"},
59	};
60	
61	constexpr MatchRule kSameInstanceUbCtpDeviceOnlyRule = {
62	    MatchRuleType::SINGLE,      HandlerCreateArgs::HandlerType::DIRECT, kProtocolUbCtp, kPlacementDevice,
63	    CommType::COMM_TYPE_UB_D2D, "same-instance device-only ub ctp"};
64	}  // namespace
65	
66	CommType EndpointMatcher::ParseCommType(const std::string &local, const std::string &remote) {
67	  if (local == kPlacementDevice && remote == kPlacementDevice) {
68	    return CommType::COMM_TYPE_UB_D2D;
69	  }
70	  if (local == kPlacementDevice && remote == kPlacementHost) {
71	    return CommType::COMM_TYPE_UB_D2H;
72	  }
73	  if (local == kPlacementHost && remote == kPlacementHost) {
74	    return CommType::COMM_TYPE_UB_H2H;
75	  }
76	  return CommType::COMM_TYPE_UB_H2D;
77	}
78	
79	bool EndpointMatcher::IsUbProtocol(const std::string &protocol) {
80	  return protocol == kProtocolUbCtp;
81	}
82	
83	static bool IsUbCtpEndpoint(const EndpointConfig &endpoint) {
84	  return endpoint.protocol == kProtocolUbCtp;
85	}
86	
87	static bool AreUbCtpEndpointsAllDevice(const std::vector<EndpointConfig> &endpoints) {
88	  return std::all_of(endpoints.begin(), endpoints.end(), [](const EndpointConfig &endpoint) {
89	    return !IsUbCtpEndpoint(endpoint) || endpoint.placement == kPlacementDevice;
90	  });
91	}
92	
93	const char *EndpointMatcher::HandlerTypeToString(HandlerCreateArgs::HandlerType type) {
94	  switch (type) {
95	    case HandlerCreateArgs::HandlerType::DIRECT:
96	      return "DIRECT";
97	    case HandlerCreateArgs::HandlerType::UB:
98	      return "UB";
99	    default:
100	      return "UNKNOWN";
101	  }
102	}
103	
104	void EndpointMatcher::BuildMatchMap(const std::vector<EndpointConfig> &endpoints,
105	                                    std::map<MatchKey, EndpointConfig> &out) {
106	  for (const auto &ep : endpoints) {
107	    if (IsUbProtocol(ep.protocol)) {
108	      out[{ep.dst_eid, ep.plane, ep.placement}] = ep;
109	    }
110	  }
111	}
112	
113	bool EndpointMatcher::IsCrossInstance(const std::vector<EndpointConfig> &local,
114	                                      const std::vector<EndpointConfig> &remote) {
115	  return local[0].net_instance_id != remote[0].net_instance_id;
116	}
117	
118	std::map<MatchKey, EndpointConfig>::const_iterator EndpointMatcher::FindMatchingKey(
119	    const std::map<MatchKey, EndpointConfig> &map, const MatchKey &query) {
120	  for (auto it = map.begin(); it != map.end(); ++it) {
121	    if (it->first.Matches(query)) {
122	      return it;
123	    }
124	  }
125	  return map.end();
126	}
127	
128	Status EndpointMatcher::TryMatchSingle(const std::vector<EndpointConfig> &local,
129	                                       const std::vector<EndpointConfig> &remote, const std::string &protocol,
130	                                       const std::string &placement, CommType type,
131	                                       std::vector<HandlerCreateArgs::EndpointPair> &pairs) {
132	  auto is_matched = [&protocol, &placement](const EndpointConfig &endpoint) {
133	    return endpoint.protocol == protocol && endpoint.placement == placement;
134	  };
135	  auto local_it = std::find_if(local.begin(), local.end(), is_matched);
136	  auto remote_it = std::find_if(remote.begin(), remote.end(), is_matched);
137	  if (local_it != local.end() && remote_it != remote.end()) {
138	    pairs.push_back({*local_it, *remote_it, type});
139	    return SUCCESS;
140	  }
141	  return FAILED;
142	}
143	
144	Status EndpointMatcher::TryMatchUb(const EndpointConfig &local, const std::map<MatchKey, EndpointConfig> &peers,
145	                                   std::map<CommType, bool> &expected, uint32_t &count,
146	                                   std::vector<HandlerCreateArgs::EndpointPair> &pairs) {
147	  if (!IsUbProtocol(local.protocol)) {
148	    return SUCCESS;
149	  }
150	  for (const auto &placement : {kPlacementDevice, kPlacementHost}) {
151	    MatchKey key{local.comm_id, local.plane, placement};
152	    auto it = FindMatchingKey(peers, key);
153	    if (it != peers.end()) {
154	      CommType type = ParseCommType(local.placement, it->second.placement);
155	      if (!expected[type]) {
156	        pairs.push_back({local, it->second, type});
157	        expected[type] = true;
158	        count++;
159	      }
160	    }
161	  }
162	  return SUCCESS;
163	}
164	
165	Status EndpointMatcher::TryMatchH2rHLoopback(const EndpointConfig &local, const std::vector<EndpointConfig> &remote,
166	                                             std::map<CommType, bool> &expected, uint32_t &count,
167	                                             std::vector<HandlerCreateArgs::EndpointPair> &pairs) {
168	  if (!IsUbProtocol(local.protocol) || local.placement != kPlacementHost || local.server_id.empty() ||
169	      expected[CommType::COMM_TYPE_UB_H2H]) {
170	    return SUCCESS;
171	  }
172	  auto is_loopback_peer = [&local](const EndpointConfig &peer) {
173	    return IsUbProtocol(peer.protocol) && peer.protocol == local.protocol && peer.placement == kPlacementHost &&
174	           peer.plane == local.plane && peer.server_id == local.server_id;
175	  };
176	  auto remote_it = std::find_if(remote.begin(), remote.end(), is_loopback_peer);
177	  if (remote_it == remote.end()) {
178	    return SUCCESS;
179	  }
180	
181	  EndpointConfig loopback_local = local;
182	  loopback_local.comm_id = remote_it->comm_id;
183	  pairs.push_back({loopback_local, *remote_it, CommType::COMM_TYPE_UB_H2H});
184	  expected[CommType::COMM_TYPE_UB_H2H] = true;
185	  count++;
186	  return SUCCESS;
187	}
188	
189	Status EndpointMatcher::TryMatchGroup(const std::vector<EndpointConfig> &local,
190	                                      const std::vector<EndpointConfig> &remote,
191	                                      std::vector<HandlerCreateArgs::EndpointPair> &pairs) {
192	  std::map<CommType, bool> expected = {{CommType::COMM_TYPE_UB_D2D, false},
193	                                       {CommType::COMM_TYPE_UB_H2D, false},
194	                                       {CommType::COMM_TYPE_UB_D2H, false},
195	                                       {CommType::COMM_TYPE_UB_H2H, false}};
196	  uint32_t count = 0;
197	  std::map<MatchKey, EndpointConfig> peers;
198	  BuildMatchMap(remote, peers);
199	  auto sorted_local = local;
200	  std::sort(sorted_local.begin(), sorted_local.end(),
201	            [](const EndpointConfig &a, const EndpointConfig &b) { return !a.dst_eid.empty() && b.dst_eid.empty(); });
202	  for (const auto &ep : sorted_local) {
203	    HIXL_CHK_STATUS_RET(TryMatchH2rHLoopback(ep, remote, expected, count, pairs));
204	    if (count == kMaxUbCsClientNum) {
205	      return SUCCESS;
206	    }
207	    HIXL_CHK_STATUS_RET(TryMatchUb(ep, peers, expected, count, pairs));
208	    if (count == kMaxUbCsClientNum) {
209	      return SUCCESS;
210	    }
211	  }
212	  return count > 0 ? SUCCESS : FAILED;
213	}
214	
215	Status EndpointMatcher::TryMatchUbCtpD2DOnlyByGroup(const std::vector<EndpointConfig> &local,
216	                                                    const std::vector<EndpointConfig> &remote,
217	                                                    std::vector<HandlerCreateArgs::EndpointPair> &pairs) {
218	  std::vector<HandlerCreateArgs::EndpointPair> group_pairs;
219	  if (TryMatchGroup(local, remote, group_pairs) != SUCCESS) {
220	    return FAILED;
221	  }
222	  if (group_pairs.size() != 1U || group_pairs[0].type != CommType::COMM_TYPE_UB_D2D ||
223	      !IsUbCtpEndpoint(group_pairs[0].local) || !IsUbCtpEndpoint(group_pairs[0].remote)) {
224	    return FAILED;
225	  }
226	  pairs = std::move(group_pairs);
227	  return SUCCESS;
228	}
229	
230	Status EndpointMatcher::TryMatchByPriority(const std::vector<EndpointConfig> &local,
231	                                           const std::vector<EndpointConfig> &remote, bool cross_instance,
232	                                           std::vector<HandlerCreateArgs::EndpointPair> &pairs,
233	                                           HandlerCreateArgs::HandlerType &handler_type) {
234	  auto try_match_rule = [&local, &remote, &pairs, &handler_type](const MatchRule &rule) -> Status {
235	    Status status = FAILED;
236	    switch (rule.rule_type) {
237	      case MatchRuleType::GROUP:
238	        status = TryMatchGroup(local, remote, pairs);
239	        break;
240	      case MatchRuleType::SINGLE:
241	        if (rule.protocol == kProtocolUbCtp && rule.type == CommType::COMM_TYPE_UB_D2D) {
242	          status = TryMatchUbCtpD2DOnlyByGroup(local, remote, pairs);
243	        } else {
244	          status = TryMatchSingle(local, remote, rule.protocol, rule.placement, rule.type, pairs);
245	        }
246	        break;
247	      default:
248	        break;
249	    }
250	    if (status == SUCCESS) {
251	      handler_type = rule.handler_type;
252	      const char *selected_protocol = (rule.protocol == nullptr) ? "ub_group" : rule.protocol;
253	      const char *selected_placement = (rule.placement == nullptr) ? "mixed" : rule.placement;
254	      HIXL_EVENT("EndpointMatcher selected link, handler:%s, reason:%s, protocol:%s, placement:%s, comm_type:%s",
255	                 HandlerTypeToString(rule.handler_type), rule.reason, selected_protocol, selected_placement,
256	                 CommTypeToString(rule.type));
257	      LogMatchedEndpoints(pairs, handler_type);
258	      return SUCCESS;
259	    }
260	    return FAILED;
261	  };
262	
263	  if (!cross_instance && AreUbCtpEndpointsAllDevice(local) && AreUbCtpEndpointsAllDevice(remote)) {
264	    if (try_match_rule(kSameInstanceUbCtpDeviceOnlyRule) == SUCCESS) {
265	      return SUCCESS;
266	    }
267	  }
268	
269	  const MatchRule *rules = cross_instance ? kCrossInstanceRules : kSameInstanceRules;
270	  const size_t rule_count = cross_instance ? sizeof(kCrossInstanceRules) / sizeof(kCrossInstanceRules[0])
271	                                           : sizeof(kSameInstanceRules) / sizeof(kSameInstanceRules[0]);
272	  for (size_t i = 0; i < rule_count; ++i) {
273	    if (try_match_rule(rules[i]) == SUCCESS) {
274	      return SUCCESS;
275	    }
276	  }
277	  HIXL_LOGE(PARAM_INVALID, "Failed to find matched endpoints");
278	  return PARAM_INVALID;
279	}
280	
281	void EndpointMatcher::LogMatchedEndpoints(const std::vector<HandlerCreateArgs::EndpointPair> &pairs,
282	                                          HandlerCreateArgs::HandlerType handler_type) {
283	  HIXL_EVENT("EndpointMatcher selected handler:%s, matched pairs:%zu", HandlerTypeToString(handler_type), pairs.size());
284	  for (size_t i = 0; i < pairs.size(); ++i) {
285	    const auto &pair = pairs[i];
286	    HIXL_EVENT("EndpointMatcher pair[%zu], comm_type:%s, local_endpoint:{%s}, remote_endpoint:{%s}", i,
287	               CommTypeToString(pair.type), pair.local.ToString().c_str(), pair.remote.ToString().c_str());
288	  }
289	}
290	
291	Status EndpointMatcher::MatchEndpoints(const std::vector<EndpointConfig> &local,
292	                                       const std::vector<EndpointConfig> &remote,
293	                                       std::vector<HandlerCreateArgs::EndpointPair> &matched_pairs,
294	                                       HandlerCreateArgs::HandlerType &handler_type) {
295	  const bool cross_instance = IsCrossInstance(local, remote);
296	  HIXL_EVENT("EndpointMatcher select start, cross_instance:%d, local_net_instance:%s, remote_net_instance:%s",
297	             static_cast<int32_t>(cross_instance), local[0].net_instance_id.c_str(), remote[0].net_instance_id.c_str());
298	  return TryMatchByPriority(local, remote, cross_instance, matched_pairs, handler_type);
299	}
300	
301	}  // namespace hixl
302

