103	                             FAILED, "GetEidList failed, logic_id=%u, urma_dev_index=%u", logic_id, dev_index);
104	    HIXL_CHK_BOOL_RET_STATUS(eid_cnt >= 0 && eid_cnt <= kMaxEidPerUe, FAILED,
