207	  }
208	  uint32_t intercon_type = 0U;
209	  HIXL_CHK_STATUS_RET(DsmiProxy::GetInterconType(logic_dev_id, intercon_type), "GetInterconType failed");
210	  HIXL_EVENT("[EndpointGenerator] DSMI InterconType=%u for user_dev_id=%d, logic_dev_id=%d", intercon_type, user_dev_id,
211	             logic_dev_id);
212	  if (IsUbgInterconType(intercon_type)) {
213	    EndpointConfig ubg_endpoint{};
214	    if (GenDefaultUbgEndpointConfig(logic_dev_id, ubg_endpoint) != SUCCESS) {
215	      HIXL_EVENT("[EndpointGenerator] UB_RTP endpoint generation failed, skip ScaleOut, fallback to UB");
216	      return SUCCESS;
217	    }
218	    endpoint_list.emplace_back(std::move(ubg_endpoint));
219	    return SUCCESS;
220	  }
221	  if (IsUboeInterconType(intercon_type)) {
222	    EndpointConfig uboe_endpoint{};
223	    if (GenDefaultUboeEndpointConfig(logic_dev_id, uboe_endpoint) != SUCCESS) {
224	      HIXL_EVENT("[EndpointGenerator] UBoE endpoint generation failed, skip ScaleOut, fallback to UB");
225	      return SUCCESS;
226	    }
227	    endpoint_list.emplace_back(std::move(uboe_endpoint));
228	    return SUCCESS;
229	  }
230	  if (IsRoceInterconType(intercon_type)) {
231	    HIXL_EVENT("[EndpointGenerator] InterconType=%u is RoCE, keep existing UB generation", intercon_type);
232	    return SUCCESS;
233	  }
234	  HIXL_LOGE(FAILED, "Unsupported DSMI InterconType=%u for ScaleOut auto endpoint generation", intercon_type);
235	  return FAILED;
236	}
