255	Status ParseIpAddress(const std::string &ip_str, CommAddr &addr) {
256	  struct in_addr ipv4_addr;
257	  (void)memset_s(&ipv4_addr, sizeof(ipv4_addr), 0, sizeof(ipv4_addr));
258	  if (inet_pton(AF_INET, ip_str.c_str(), &ipv4_addr) == 1) {
259	    addr.type = COMM_ADDR_TYPE_IP_V4;
260	    addr.addr = ipv4_addr;
261	    return SUCCESS;
262	  }
263	
264	  struct in6_addr ipv6_addr;
265	  (void)memset_s(&ipv6_addr, sizeof(ipv6_addr), 0, sizeof(ipv6_addr));
266	  if (inet_pton(AF_INET6, ip_str.c_str(), &ipv6_addr) == 1) {
267	    addr.type = COMM_ADDR_TYPE_IP_V6;
268	    addr.addr6 = ipv6_addr;
269	    return SUCCESS;
270	  }
271	
272	  HIXL_LOGE(PARAM_INVALID, "Invalid IP address: %s", ip_str.c_str());
273	  return PARAM_INVALID;
274	}
