276	Status ParseHccsCommId(const std::string &comm_id_str, uint32_t &device_id) {
277	  constexpr size_t kMaxHccsCommIdLen = 10U;
278	  HIXL_CHK_BOOL_RET_STATUS(!comm_id_str.empty() && comm_id_str.length() <= kMaxHccsCommIdLen, PARAM_INVALID,
279	                           "Invalid hccs comm_id length:%zu, max:%zu", comm_id_str.length(), kMaxHccsCommIdLen);
280	  HIXL_CHK_BOOL_RET_STATUS(
281	      std::all_of(comm_id_str.begin(), comm_id_str.end(), [](unsigned char c) { return std::isdigit(c); }),
282	      PARAM_INVALID, "Invalid hccs comm_id:%s", comm_id_str.c_str());
283	
284	  uint64_t parsed = 0;
285	  for (const unsigned char c : comm_id_str) {
286	    parsed = parsed * 10U + static_cast<uint64_t>(c - '0');
287	    HIXL_CHK_BOOL_RET_STATUS(parsed <= static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()), PARAM_INVALID,
288	                             "hccs comm_id out of range:%s", comm_id_str.c_str());
289	  }
290	  device_id = static_cast<uint32_t>(parsed);
291	  return SUCCESS;
292	}
