294	Status ParseEidAddress(const std::string &eid_str, CommAddr &addr) {
295	  HIXL_CHK_BOOL_RET_STATUS(eid_str.length() == kEidHexStrLen, PARAM_INVALID,
296	                           "Invalid EID format:%s, expected %zu hexadecimal characters without colons", eid_str.c_str(),
297	                           kEidHexStrLen);
298	  HIXL_CHK_BOOL_RET_STATUS(
299	      std::all_of(eid_str.begin(), eid_str.end(), [](unsigned char c) { return std::isxdigit(c); }), PARAM_INVALID,
300	      "Invalid EID:%s, only hexadecimal characters are allowed", eid_str.c_str());
301	
302	  (void)memset_s(addr.eid, COMM_ADDR_EID_LEN, 0, COMM_ADDR_EID_LEN);
303	  for (size_t i = 0; i < COMM_ADDR_EID_LEN; ++i) {
304	    const std::string segment = eid_str.substr(i * 2, 2);
305	    try {
306	      const unsigned long value = std::stoul(segment, nullptr, 16);
307	      HIXL_CHK_BOOL_RET_STATUS(value <= UINT8_MAX, PARAM_INVALID,
308	                               "Invalid segment:%zu in EID:%s, maximum value is 0xFF", i, segment.c_str());
309	      addr.eid[i] = static_cast<uint8_t>(value);
310	    } catch (const std::invalid_argument &) {
311	      HIXL_LOGE(PARAM_INVALID, "Failed to convert segment %zu of EID: %s to integer.", i, segment.c_str());
312	      return PARAM_INVALID;
313	    } catch (const std::out_of_range &) {
314	      HIXL_LOGE(PARAM_INVALID, "Segment %zu of EID: %s is out of range.", i, segment.c_str());
315	      return PARAM_INVALID;
316	    }
317	  }
318	  addr.type = COMM_ADDR_TYPE_EID;
319	  return SUCCESS;
320	}
