381	bool IsSupportedProtocolDesc(const std::string &protocol, const std::string &placement) {
382	  static const std::set<std::string> kSupportedProtocols = {kProtocolRoce, kProtocolHccs, kProtocolUbCtp, kProtocolUboe,
383	                                                            kProtocolUbRtp};
384	  static const std::set<std::string> kSupportedPlacements = {kPlacementHost, kPlacementDevice};
385	  if (kSupportedProtocols.find(protocol) == kSupportedProtocols.end() ||
386	      kSupportedPlacements.find(placement) == kSupportedPlacements.end()) {
387	    return false;
388	  }
389	  if ((protocol == kProtocolUboe || protocol == kProtocolUbRtp) && placement != kPlacementDevice) {
390	    return false;
391	  }
392	  return true;
393	}
