395	Status ParseProtocolDesc(const std::vector<std::string> &protocol_desc, std::set<std::string> &desc_set) {
396	  desc_set.clear();
397	  for (const auto &desc : protocol_desc) {
398	    const auto split_pos = desc.find(':');
399	    HIXL_CHK_BOOL_RET_STATUS(split_pos != std::string::npos && split_pos > 0U && split_pos + 1U < desc.size() &&
400	                                 desc.find(':', split_pos + 1U) == std::string::npos,
401	                             PARAM_INVALID, "Invalid protocol_desc:%s, expected format protocol:placement",
402	                             desc.c_str());
403	    const std::string protocol = desc.substr(0, split_pos);
404	    const std::string placement = desc.substr(split_pos + 1U);
405	    HIXL_CHK_BOOL_RET_STATUS(IsSupportedProtocolDesc(protocol, placement), PARAM_INVALID,
406	                             "Unsupported protocol_desc:%s", desc.c_str());
407	    desc_set.insert(BuildProtocolDescKey(protocol, placement));
408	  }
409	  return SUCCESS;
410	}
411	
412	ProtocolDescMode ParseProtocolDescMode(const std::vector<std::string> &protocol_desc) {
413	  if (protocol_desc.empty()) {
414	    return ProtocolDescMode::kNone;
415	  }
416	  const bool has_uboe = std::find(protocol_desc.begin(), protocol_desc.end(), kUboeProtocolDesc) != protocol_desc.end();
417	  const bool has_ub_rtp =
418	      std::find(protocol_desc.begin(), protocol_desc.end(), kUbRtpProtocolDesc) != protocol_desc.end();
419	  if (has_uboe && has_ub_rtp) {
420	    return ProtocolDescMode::kConflict;
421	  }
422	  if (has_uboe) {
423	    return ProtocolDescMode::kUboe;
424	  }
425	  if (has_ub_rtp) {
426	    return ProtocolDescMode::kUbg;
427	  }
428	  return ProtocolDescMode::kNone;
429	}
