431	// 与 IsA5UbAutoGenNeeded / GetA5UbGenerateMode 等价，入参为已拆分 protocol_desc
432	Status ResolveUbCtpNeedAndMode(const std::vector<std::string> &protocol_desc, bool &ub_needed,
433	                               LocalCommResGenerateMode &mode) {
434	  ub_needed = false;
435	  mode = LocalCommResGenerateMode::kDeviceOnly;
436	  if (protocol_desc.empty()) {
437	    ub_needed = true;
438	    return SUCCESS;
439	  }
440	  std::set<std::string> desc_set;
441	  HIXL_CHK_STATUS_RET(ParseProtocolDesc(protocol_desc, desc_set), "ParseProtocolDesc failed");
442	  const std::string device_key = BuildProtocolDescKey(kProtocolUbCtp, kPlacementDevice);
443	  const std::string host_key = BuildProtocolDescKey(kProtocolUbCtp, kPlacementHost);
444	  ub_needed = desc_set.count(device_key) > 0 || desc_set.count(host_key) > 0;
445	  if (desc_set.count(host_key) > 0) {
446	    mode = LocalCommResGenerateMode::kDeviceAndHost;
447	  }
448	  return SUCCESS;
449	}
