451	Status FilterEndpointsByProtocolDescList(const std::vector<std::string> &protocol_desc,
452	                                         std::vector<EndpointConfig> &endpoint_list) {
453	  if (protocol_desc.empty()) {
454	    return SUCCESS;
455	  }
456	  std::set<std::string> desc_set;
457	  HIXL_CHK_STATUS_RET(ParseProtocolDesc(protocol_desc, desc_set), "ParseProtocolDesc failed");
458	  std::vector<EndpointConfig> filtered;
459	  filtered.reserve(endpoint_list.size());
460	  for (auto &ep : endpoint_list) {
461	    if (desc_set.find(BuildProtocolDescKey(ep.protocol, ep.placement)) != desc_set.end()) {
462	      filtered.emplace_back(std::move(ep));
463	    }
464	  }
465	  endpoint_list = std::move(filtered);
466	  HIXL_CHK_BOOL_RET_STATUS(!endpoint_list.empty(), PARAM_INVALID,
467	                           "endpoint_list is empty after filtering by protocol_desc");
468	  return SUCCESS;
469	}
