471	// protocol_desc 非空时按显式模式生成 ScaleOut（ub_rtp/uboe）端点
472	Status GenScaleOutByProtocolDesc(int32_t device_id, const std::vector<std::string> &protocol_desc,
473	                                 std::vector<EndpointConfig> &endpoint_list) {
474	  const ProtocolDescMode mode = ParseProtocolDescMode(protocol_desc);
475	  HIXL_CHK_BOOL_RET_STATUS(mode != ProtocolDescMode::kConflict, PARAM_INVALID,
476	                           "protocol_desc cannot contain both %s and %s", kUbRtpProtocolDesc, kUboeProtocolDesc);
477	  if (mode != ProtocolDescMode::kUboe && mode != ProtocolDescMode::kUbg) {
478	    return SUCCESS;
479	  }
480	  int32_t logic_dev_id = 0;
481	  HIXL_CHK_ACL_RET(aclrtGetLogicDevIdByUserDevId(device_id, &logic_dev_id));
482	  if (DsmiProxy::IsInterconTypeSupported()) {
483	    uint32_t intercon_type = 0U;
484	    HIXL_CHK_STATUS_RET(DsmiProxy::GetInterconType(logic_dev_id, intercon_type), "GetInterconType failed");
485	    const bool match =
486	        (mode == ProtocolDescMode::kUbg) ? IsUbgInterconType(intercon_type) : IsUboeInterconType(intercon_type);
487	    const char *desc = (mode == ProtocolDescMode::kUbg) ? kUbRtpProtocolDesc : kUboeProtocolDesc;
488	    HIXL_CHK_BOOL_RET_STATUS(match, FAILED, "protocol_desc=%s conflicts with InterconType=%u", desc, intercon_type);
489	  }
490	  EndpointConfig endpoint{};
491	  if (mode == ProtocolDescMode::kUbg) {
492	    HIXL_CHK_STATUS_RET(GenDefaultUbgEndpointConfig(logic_dev_id, endpoint), "GenDefaultUbRtpEndpointConfig failed");
493	  } else {
494	    HIXL_CHK_STATUS_RET(GenDefaultUboeEndpointConfig(logic_dev_id, endpoint), "GenDefaultUboeEndpointConfig failed");
495	  }
496	  endpoint_list.emplace_back(std::move(endpoint));
497	  return SUCCESS;
498	}
