569	Status EndpointGenerator::ParseEndpointListFromLocalCommRes(const HixlOptions &options, std::string &local_comm_res,
570	                                                            std::vector<EndpointConfig> &endpoint_list) {
571	  endpoint_list.clear();
572	
573	  auto lcr = options.LocalCommRes();
574	  const char *local_comm_res_cstr = lcr.has_value() ? lcr->c_str() : nullptr;
575	  if (local_comm_res_cstr == nullptr || local_comm_res_cstr[0] == '\0') {
576	    local_comm_res.clear();
577	    return SUCCESS;
578	  }
579	
580	  local_comm_res = local_comm_res_cstr;
581	  try {
582	    nlohmann::json config = nlohmann::json::parse(local_comm_res);
583	    bool has_valid_endpoint_list = config.contains("net_instance_id") && config["net_instance_id"].is_string() &&
584	                                   config.contains("endpoint_list") && config["endpoint_list"].is_array() &&
585	                                   !config["endpoint_list"].empty();
586	    if (!has_valid_endpoint_list) {
587	      return SUCCESS;
588	    }
589	    HIXL_CHK_STATUS_RET(ParseLocalCommRes(config, endpoint_list), "ParseLocalCommRes failed");
590	    HIXL_CHK_STATUS_RET(FilterEndpointListByProtocolDesc(options, endpoint_list),
591	                        "FilterEndpointListByProtocolDesc failed");
592	  } catch (const nlohmann::json::exception &e) {
593	    HIXL_LOGE(PARAM_INVALID, "Parse local_comm_res failed, exception:%s", e.what());
594	    return PARAM_INVALID;
595	  }
596	  return SUCCESS;
597	}
