605	      return SUCCESS;
606	    case ProtocolDescMode::kConflict:
607	      HIXL_LOGE(PARAM_INVALID, "protocol_desc cannot contain both %s and %s", kUbRtpProtocolDesc, kUboeProtocolDesc);
608	      return PARAM_INVALID;
609	    case ProtocolDescMode::kUboe:
610	    case ProtocolDescMode::kUbg:
