632	Status EndpointGenerator::BuildEndpointList(const HixlOptions &options, const std::string &local_engine,
633	                                            std::string &local_comm_res, std::vector<EndpointConfig> &endpoint_list) {
634	  endpoint_list.clear();
635	
636	  // Step 1: Parse endpoint_list from localCommRes
637	  HIXL_CHK_STATUS_RET(ParseEndpointListFromLocalCommRes(options, local_comm_res, endpoint_list),
638	                      "ParseEndpointListFromLocalCommRes failed");
639	  if (!endpoint_list.empty()) {
640	    if (IsIntraRoceEnabled()) {
641	      HIXL_LOGI("HCCL_INTRA_ROCE_ENABLE=1, filter to RoCE only");
642	      endpoint_list.erase(std::remove_if(endpoint_list.begin(), endpoint_list.end(),
643	                                         [](const EndpointConfig &ep) { return ep.protocol != kProtocolRoce; }),
644	                          endpoint_list.end());
645	    }
646	    HIXL_CHK_STATUS_RET(PopulateLocalDeviceInfo(endpoint_list), "PopulateLocalDeviceInfo failed");
647	    return SUCCESS;
648	  }
649	
650	  uint32_t device_count = 0;
651	  HIXL_CHK_ACL_RET(aclrtGetDeviceCount(&device_count), "aclrtGetDeviceCount failed");
652	  HIXL_CHK_BOOL_RET_STATUS(device_count > 0U, PARAM_INVALID,
653	                           "LocalCommRes with endpoint_list is required when no local NPU device exists; "
654	                           "auto generation is not supported on generic server");
655	
656	  // Step 2: Build default endpoint list based on soc type
657	  HIXL_CHK_STATUS_RET(AutoGenEndpointList(options, local_engine, endpoint_list), "AutoGenEndpointList failed");
658	  HIXL_CHK_BOOL_RET_STATUS(!endpoint_list.empty(), PARAM_INVALID,
659	                           "[HixlEngine] endpoint_list is empty after all generation attempts");
660	  HIXL_CHK_STATUS_RET(PopulateLocalDeviceInfo(endpoint_list), "PopulateLocalDeviceInfo failed");
661	  return SUCCESS;
662	}
