664	Status EndpointGenerator::AutoGenA5EndpointList(const HixlOptions &options, std::vector<EndpointConfig> &endpoint_list,
665	                                                const std::string &topo_path) {
666	  int32_t device_id = 0;
667	  HIXL_CHK_ACL_RET(aclrtGetDevice(&device_id));
668	  int32_t phy_id = 0;
669	  HIXL_CHK_ACL_RET(aclrtGetPhyDevIdByLogicDevId(device_id, &phy_id));
670	
671	  if (IsIntraRoceEnabled()) {
672	    HIXL_LOGI("[AutoGenEndpointList] HCCL_INTRA_ROCE_ENABLE=1, skip ScaleOut and UB generation");
673	    return SUCCESS;
674	  }
675	
676	  HIXL_LOGI("[AutoGenEndpointList] A5 auto-generate: device_id=%d, phy_id=%d", device_id, phy_id);
677	  std::string net_instance_id;
678	  // topo_path 为空：使用默认 topo；protocol_desc 来自 options
679	  HIXL_CHK_STATUS_RET(
680	      AutoGenA5Core(device_id, phy_id, topo_path, options.GetProtocolDesc(), endpoint_list, net_instance_id),
681	      "[AutoGenEndpointList] AutoGenA5Core failed");
