685	Status EndpointGenerator::AutoGenEndpointList(const HixlOptions &options, const std::string &local_engine,
686	                                              std::vector<EndpointConfig> &endpoint_list,
687	                                              const std::string &topo_path) {
688	  SocType soc_type = SocType::kOther;
689	  HIXL_CHK_STATUS_RET(GetSocType(soc_type), "GetSocType failed");
690	  endpoint_list.clear();
691	
692	  if (soc_type == SocType::kV5) {
693	    // AutoGenA5Core 内部已按 protocol_desc 过滤，此处不再重复 Filter
694	    HIXL_CHK_STATUS_RET(AutoGenA5EndpointList(options, endpoint_list, topo_path), "AutoGenA5EndpointList failed");
695	    HIXL_EVENT("[AutoGenEndpointList] ScaleOut generated %zu endpoints", endpoint_list.size());
696	    return SUCCESS;
697	  }
698	  if (soc_type == SocType::kV2 || soc_type == SocType::kV3) {
699	    int32_t device_id = 0;
700	    HIXL_CHK_ACL_RET(aclrtGetDevice(&device_id));
701	    LocCommResInfo loc_comm_res_info{};
702	    HIXL_CHK_STATUS_RET(GenerateInfo(device_id, local_engine, loc_comm_res_info), "GenerateInfo failed");
703	    ConvertLocCommResInfoToEndpointList(loc_comm_res_info, endpoint_list);
704	  }
705	
706	  if (endpoint_list.empty()) {
707	    return SUCCESS;
708	  }
709	  HIXL_CHK_STATUS_RET(FilterEndpointListByProtocolDesc(options, endpoint_list),
710	                      "FilterEndpointListByProtocolDesc failed");
711	  return SUCCESS;
712	}
