714	Status EndpointGenerator::ConvertToEndpointDesc(const EndpointConfig &endpoint_config, EndpointDesc &endpoint) {
715	  HIXL_CHK_STATUS_RET(ParseEndpointPlacement(endpoint_config, endpoint), "ParseEndpointPlacement failed");
716	  HIXL_CHK_STATUS_RET(ParseEndpointProtocol(endpoint_config, endpoint), "ParseEndpointProtocol failed");
717	  if (endpoint.loc.locType == ENDPOINT_LOC_TYPE_DEVICE) {
718	    HIXL_CHK_STATUS_RET(FillEndpointDeviceLocation(endpoint_config, endpoint), "FillEndpointDeviceLocation failed");
719	  }
720	
721	  if (endpoint_config.protocol == kProtocolRoce || endpoint_config.protocol == kProtocolUboe) {
722	    HIXL_CHK_STATUS_RET(ParseIpAddress(endpoint_config.comm_id, endpoint.commAddr), "ParseIpAddress failed");
723	    return SUCCESS;
724	  }
725	
726	  if (endpoint_config.protocol == kProtocolHccs) {
727	    uint32_t device_id = 0;
728	    HIXL_CHK_STATUS_RET(ParseHccsCommId(endpoint_config.comm_id, device_id), "ParseHccsCommId failed");
729	    endpoint.commAddr.type = COMM_ADDR_TYPE_ID;
730	    endpoint.commAddr.id = device_id;
731	    return SUCCESS;
732	  }
733	
734	  if (endpoint_config.protocol == kProtocolUbCtp || endpoint_config.protocol == kProtocolUbRtp) {
735	    HIXL_CHK_STATUS_RET(ParseEidAddress(endpoint_config.comm_id, endpoint.commAddr), "ParseEidAddress failed");
736	  }
737	  return SUCCESS;
738	}
