740	Status EndpointGenerator::SerializeEndpointConfigList(const std::vector<EndpointConfig> &list, std::string &msg_str) {
741	  nlohmann::json j = nlohmann::json::array();
742	  try {
743	    for (const auto &ep : list) {
744	      nlohmann::json item;
745	      item["protocol"] = ep.protocol;
746	      item["comm_id"] = ep.comm_id;
747	      item["placement"] = ep.placement;
748	      item["plane"] = ep.plane;
749	      item["dst_eid"] = ep.dst_eid;
750	      item["net_instance_id"] = ep.net_instance_id;
751	      item["server_id"] = ep.server_id;
752	
753	      nlohmann::json device_info;
754	      device_info["phy_device_id"] = ep.device_info.phy_device_id;
755	      device_info["super_device_id"] = ep.device_info.super_device_id;
756	      device_info["super_pod_id"] = ep.device_info.super_pod_id;
757	      item["device_info"] = device_info;
758	
759	      j.push_back(item);
760	    }
761	    msg_str = j.dump();
762	  } catch (const nlohmann::json::exception &e) {
763	    HIXL_LOGE(PARAM_INVALID, "Failed to dump endpoint list, exception:%s", e.what());
764	    return PARAM_INVALID;
765	  }
766	  return SUCCESS;
767	}
