769	Status EndpointGenerator::DeserializeEndpointConfigList(const std::string &json_str,
770	                                                        std::vector<EndpointConfig> &endpoint_list) {
771	  nlohmann::json j;
772	  try {
773	    j = nlohmann::json::parse(json_str);
774	  } catch (const nlohmann::json::exception &e) {
775	    HIXL_LOGE(PARAM_INVALID, "Failed to parse json, exception:%s", e.what());
776	    return PARAM_INVALID;
777	  }
778	  if (!j.is_array()) {
779	    HIXL_LOGE(PARAM_INVALID, "Invalid json format, expect array");
780	    return PARAM_INVALID;
781	  }
782	
783	  endpoint_list.clear();
784	  for (const auto &item : j) {
785	    EndpointConfig endpoint{};
786	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "protocol", endpoint.protocol), "Failed to parse protocol");
787	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "comm_id", endpoint.comm_id), "Failed to parse comm_id");
788	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "net_instance_id", endpoint.net_instance_id),
789	                        "Failed to parse net_instance_id");
790	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "placement", endpoint.placement), "Failed to parse placement");
791	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "plane", endpoint.plane), "Failed to parse plane");
792	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "dst_eid", endpoint.dst_eid), "Failed to parse dst_eid");
793	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "server_id", endpoint.server_id, false), "Failed to parse server_id");
794	    ParseDeviceInfo(item, endpoint);
795	    endpoint_list.emplace_back(std::move(endpoint));
796	  }
797	  return SUCCESS;
798	}
