850	Status EndpointGenerator::ParseLocalCommRes(const nlohmann::json &config, std::vector<EndpointConfig> &endpoint_list) {
851	  HIXL_CHK_BOOL_RET_STATUS(config.contains("net_instance_id") && config["net_instance_id"].is_string(), PARAM_INVALID,
852	                           "local_comm_res missing net_instance_id");
853	  HIXL_CHK_BOOL_RET_STATUS(config.contains("endpoint_list") && config["endpoint_list"].is_array(), PARAM_INVALID,
854	                           "local_comm_res missing endpoint_list");
855	
856	  const std::string net_instance_id = config["net_instance_id"].get<std::string>();
857	  endpoint_list.clear();
858	  bool has_ubg = false;
859	  bool has_uboe = false;
860	  for (const auto &item : config["endpoint_list"]) {
861	    EndpointConfig endpoint{};
862	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "protocol", endpoint.protocol), "Failed to parse protocol");
863	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "comm_id", endpoint.comm_id), "Failed to parse comm_id");
864	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "placement", endpoint.placement), "Failed to parse placement");
865	    HIXL_CHK_BOOL_RET_STATUS(IsSupportedProtocolDesc(endpoint.protocol, endpoint.placement), PARAM_INVALID,
866	                             "Unsupported endpoint protocol or placement: %s:%s", endpoint.protocol.c_str(),
867	                             endpoint.placement.c_str());
868	    if (endpoint.protocol == kProtocolUbRtp) {
869	      has_ubg = true;
870	    } else if (endpoint.protocol == kProtocolUboe) {
871	      has_uboe = true;
872	    }
873	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "plane", endpoint.plane, false), "Failed to parse plane");
874	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "dst_eid", endpoint.dst_eid, false), "Failed to parse dst_eid");
875	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "server_id", endpoint.server_id, false), "Failed to parse server_id");
876	    endpoint.net_instance_id = net_instance_id;
877	    ParseDeviceInfo(item, endpoint);
878	    endpoint_list.emplace_back(std::move(endpoint));
879	  }
880	  HIXL_CHK_BOOL_RET_STATUS(!(has_ubg && has_uboe), PARAM_INVALID,
881	                           "endpoint_list cannot contain both ub_rtp and uboe protocols");
882	  HIXL_CHK_BOOL_RET_STATUS(!endpoint_list.empty(), PARAM_INVALID,
883	                           "[HixlEngine] endpoint_list is empty, please check local_comm_res");
884	  return SUCCESS;
885	}
