892	Status EndpointGenerator::PopulateLocalDeviceInfo(std::vector<EndpointConfig> &endpoint_list) {
893	  if (!HasDeviceEndpoint(endpoint_list)) {
894	    return SUCCESS;
895	  }
896	
897	  uint32_t device_count = 0;
898	  HIXL_CHK_ACL_RET(aclrtGetDeviceCount(&device_count), "aclrtGetDeviceCount failed");
899	  HIXL_CHK_BOOL_RET_STATUS(device_count > 0U, PARAM_INVALID,
900	                           "device endpoint requires local NPU device, but device count is 0");
901	
902	  SocType soc_type = SocType::kOther;
903	  HIXL_CHK_STATUS_RET(GetSocType(soc_type), "GetSocType failed");
904	  int32_t logic_device_id = 0;
905	  HIXL_CHK_ACL_RET(aclrtGetDevice(&logic_device_id));
906	  int32_t phy_device_id = -1;
907	  HIXL_CHK_ACL_RET(aclrtGetPhyDevIdByLogicDevId(logic_device_id, &phy_device_id));
908	
909	  int64_t super_device_id = -1;
910	  int64_t super_pod_id = -1;
911	  if (soc_type == SocType::kV3) {
912	    HIXL_CHK_ACL_RET(
913	        aclrtGetDeviceInfo(static_cast<uint32_t>(logic_device_id), ACL_DEV_ATTR_SUPER_POD_ID, &super_pod_id));
914	    HIXL_CHK_ACL_RET(
915	        aclrtGetDeviceInfo(static_cast<uint32_t>(logic_device_id), ACL_DEV_ATTR_SUPER_POD_DEVIDE_ID, &super_device_id));
916	  }
917	
918	  for (auto &ep : endpoint_list) {
919	    if (ep.placement != kPlacementDevice) {
920	      continue;
921	    }
922	    ep.device_info.phy_device_id = phy_device_id;
923	    ep.device_info.super_device_id = super_device_id;
924	    ep.device_info.super_pod_id = super_pod_id;
925	  }
926	  return SUCCESS;
927	}
