28	
29	EidByte6Info ParseEidByte6(const std::string &eid) {
30	  constexpr size_t kEidMinStrLen = 12U;
31	  constexpr size_t kByte6StrOffset = 10U;
32	  constexpr size_t kByteStrLen = 2U;
33	  constexpr int32_t kHexBase = 16;
34	  constexpr int32_t kNibbleShift = 4;
35	  constexpr uint8_t kNibbleMask = 0xFU;
36	  constexpr uint8_t kDieIdBit = 0x4U;
37	  constexpr uint8_t kPgEidValue1 = 0x3U;
38	  constexpr uint8_t kPgEidValue2 = 0x7U;
39	
40	  EidByte6Info info{};
41	  if (eid.length() < kEidMinStrLen) {
42	    return info;
43	  }
44	
45	  try {
46	    std::string byte_str = eid.substr(kByte6StrOffset, kByteStrLen);
47	    info.byte6 = static_cast<uint8_t>(std::stoi(byte_str, nullptr, kHexBase));
48	    info.high_nibble = static_cast<uint8_t>((info.byte6 >> kNibbleShift) & kNibbleMask);
49	    info.low_nibble = static_cast<uint8_t>(info.byte6 & kNibbleMask);
50	    info.die_id = (info.high_nibble & kDieIdBit) != 0 ? 1U : 0U;
51	    info.is_pg_eid = (info.high_nibble == kPgEidValue1 || info.high_nibble == kPgEidValue2);
52	    info.port = static_cast<int32_t>(info.low_nibble);
53	  } catch (...) {
54	    info = EidByte6Info{};
55	  }
56	  return info;
57	}
