69	std::string ConvertEidToString(const unsigned char *raw, size_t len) {
70	  if (raw == nullptr || len < static_cast<size_t>(kDcmiUrmaEidSize)) {
71	    return "";
72	  }
73	  std::ostringstream oss;
74	  for (int32_t k = 0; k < kDcmiUrmaEidSize; ++k) {
75	    oss << std::hex << std::setfill('0') << std::setw(kSetwWidth) << static_cast<int>(raw[k]);
76	  }
77	  return oss.str();
