86	  HIXL_CHK_BOOL_RET_STATUS(logic_ret == 0, FAILED, "Call api:GetLogicIdFromPhyId failed, ret:%d, npu_id:%d", logic_ret,
87	                           npu_id);
88	
89	  uint32_t dev_cnt = 0;
90	  int32_t ret = DcmiProxy::GetUrmaDeviceCnt(logic_id, &dev_cnt);
91	  HIXL_CHK_BOOL_RET_STATUS(ret == 0, FAILED, "Call api:GetUrmaDeviceCnt failed, ret:%d, logic_id:%u", ret, logic_id);
92	
93	  for (size_t i = 0; i < dev_cnt; ++i) {
94	    UrmaDevice urma_dev;
