176	// urma_admin 命令执行函数
177	int32_t DefaultUrmaAdminExec(const std::string &cmd, std::string &output) {
178	  auto urma_path = GetUrmaAdminPath();
179	  HIXL_LOGI("[DefaultUrmaAdminExec] resolved urma_admin path: '%s'", urma_path.c_str());
180	  if (urma_path.empty()) {
181	    HIXL_LOGW("[DefaultUrmaAdminExec] urma_admin not found");
182	    return FAILED;
183	  }
184	  std::string full_cmd = urma_path + " " + cmd;
185	  HIXL_LOGI("[DefaultUrmaAdminExec] exec cmd: '%s'", full_cmd.c_str());
186	  FILE *raw_pipe = popen(full_cmd.c_str(), "r");
187	  if (raw_pipe == nullptr) {
188	    HIXL_LOGW("[DefaultUrmaAdminExec] Failed to execute: %s, errno=%d(%s)", full_cmd.c_str(), errno, strerror(errno));
189	    return FAILED;
190	  }
191	  auto pipe_deleter = [](FILE *f) {
192	    if (f) {
193	      pclose(f);
194	    }
195	  };
196	  std::unique_ptr<FILE, decltype(pipe_deleter)> pipe(raw_pipe, pipe_deleter);
197	
198	  char buf[512];
199	  while (fgets(buf, sizeof(buf), pipe.get()) != nullptr) {
200	    output += buf;
201	  }
202	  HIXL_LOGI("[DefaultUrmaAdminExec] output length: %zu bytes, raw output:\n%s", output.size(), output.c_str());
203	  return SUCCESS;
204	}
