206	// 解析 urma_admin show 输出，提取所有 EID 条目
207	int32_t ParseUrmaAdminOutput(const std::string &cmd_output, std::vector<UrmaEidEntry> &all_entries) {
208	  HIXL_LOGI("[ParseUrmaAdminOutput] urma_admin output length: %zu bytes", cmd_output.length());
209	  HIXL_CHK_BOOL_RET_STATUS(!cmd_output.empty(), FAILED, "[ParseUrmaAdminOutput] urma_admin output is empty");
210	  // 打印前 500 字符用于调试
211	  std::string output_preview = cmd_output.length() > 500 ? cmd_output.substr(0, 500) + "..." : cmd_output;
212	  HIXL_LOGI("[ParseUrmaAdminOutput] urma_admin output preview:\n%s", output_preview.c_str());
213	
214	  std::istringstream stream(cmd_output);
215	  std::string line;
216	  while (std::getline(stream, line)) {
217	    // 跳过表头和分隔线
218	    if ((line.find("num") != std::string::npos && line.find("ubep_dev") != std::string::npos) ||
219	        line.find("---") != std::string::npos || line.find("eid") == std::string::npos) {
220	      continue;
221	    }
222	
223	    // 解析格式: "0 udma3 UB eid1 0000:0000:003f:0600:0010:0000:df00:1001 ACTIVE"
224	    std::istringstream iss(line);
225	    std::string num_str, udma_name, tp_type, eid_name, eid_value, link_status;
226	    iss >> num_str >> udma_name >> tp_type >> eid_name >> eid_value >> link_status;
227	
228	    if (udma_name.empty() || eid_name.empty() || eid_value.empty()) {
229	      continue;
230	    }
231	
232	    // 提取 eid_index: "eid1" → 1
233	    int eid_index = 0;
234	    try {
235	      // "eid" 前缀长度为 3，跳过前缀取数字部分
236	      eid_index = std::stoi(eid_name.substr(std::strlen("eid")));
237	    } catch (const std::exception &) {
238	      continue;
239	    }
240	
241	    UrmaEidEntry entry;
242	    entry.udma_name = udma_name;
243	    entry.eid_index = eid_index;
244	    entry.eid = eid_value;
245	    all_entries.push_back(entry);
246	  }
247	
248	  HIXL_CHK_BOOL_RET_STATUS(!all_entries.empty(), FAILED,
249	                           "[ParseUrmaAdminOutput] No entries parsed from urma_admin show output");
250	  HIXL_LOGI("[ParseUrmaAdminOutput] Successfully parsed %zu entries", all_entries.size());
251	  return SUCCESS;
252	}
