254	// Extract CPU+die key (e.g. "c1d1") from UB dev name like "udmac1d1e2".
255	// The key is the concatenation of the 'c' segment and 'd' segment (each char + its digit).
256	std::string ExtractCpuDieKey(const std::string &ub_dev_name) {
257	  size_t c_pos = ub_dev_name.find('c');
258	  size_t d_pos = ub_dev_name.find('d', (c_pos == std::string::npos) ? 0 : c_pos + 1);
259	  if (c_pos == std::string::npos || d_pos == std::string::npos || d_pos + 1 >= ub_dev_name.size()) {
260	    return "";
261	  }
262	  // c segment: "cX", d segment: "dY" → "cXdY"
263	  return ub_dev_name.substr(c_pos, 2) +
264	         ub_dev_name.substr(d_pos, 2);  // CPU and die information each occupy 2 characters.
265	}
