267	// Build CPU+die key → Host PG EID map from urma_admin entries.
268	// A Host 8-port PG group has eid_count >= 8 and contains a PG EID.
269	int32_t BuildCpuDieToHostPgEidMap(const std::vector<UrmaEidEntry> &all_entries,
270	                                  std::map<std::string, std::string> &cpu_die_to_pg_eid) {
271	  std::map<std::string, std::vector<UrmaEidEntry>> udma_groups;
272	  for (const auto &entry : all_entries) {
273	    udma_groups[entry.udma_name].push_back(entry);
274	  }
275	
276	  for (const auto &[name, entries] : udma_groups) {
277	    if (entries.size() < kNpuGroupSize) {
278	      continue;
279	    }
280	    std::string cpu_die_key = ExtractCpuDieKey(name);
281	    if (cpu_die_key.empty()) {
282	      continue;
283	    }
284	    HIXL_LOGI("[BuildCpuDieToHostPgEidMap] Host UDMA group: %s (eid_count=%zu, cpu_die_key=%s)", name.c_str(),
285	              entries.size(), cpu_die_key.c_str());
286	    for (const auto &entry : entries) {
287	      std::string eid_no_colon = FormatEidFromUrma(entry.eid);
288	      auto info = ParseEidByte6(eid_no_colon);
289	      if (info.is_pg_eid) {
290	        cpu_die_to_pg_eid[cpu_die_key] = eid_no_colon;
291	        HIXL_LOGI("[BuildCpuDieToHostPgEidMap] PG EID for %s: %s", cpu_die_key.c_str(), eid_no_colon.c_str());
292	        break;
293	      }
294	    }
295	  }
296	
297	  HIXL_CHK_BOOL_RET_STATUS(!cpu_die_to_pg_eid.empty(), FAILED,
298	                           "[BuildCpuDieToHostPgEidMap] No Host PG EID found (no UDMA group with eid_count >= 8)");
299	  return SUCCESS;
300	}
