302	// Find remote_eid for Server: standalone non-PG EID on non-mesh die (die 0).
303	// The UDMA device has exactly 1 EID with no PG.
304	int32_t FindServerRemoteEid(const std::vector<UrmaDevice> &urma_devices, int32_t mesh_die_id, std::string &remote_eid) {
305	  int32_t non_mesh_die = 1 - mesh_die_id;
306	  for (const auto &dev : urma_devices) {
307	    if (dev.eid_list.size() != 1) {
308	      continue;
309	    }
310	    auto info = ParseEidByte6(dev.eid_list[0]);
311	    if (info.die_id != non_mesh_die || info.is_pg_eid) {
312	      continue;
313	    }
314	    remote_eid = dev.eid_list[0];
315	    HIXL_LOGI("[FindServerRemoteEid] remote_eid=%s (die_id=%d, standalone non-PG)", remote_eid.c_str(), non_mesh_die);
316	    return SUCCESS;
317	  }
318	  HIXL_LOGE(FAILED, "[FindServerRemoteEid] No standalone non-PG EID found on die %d", non_mesh_die);
319	  return FAILED;
320	}
