322	// Find remote_eid for PoD: PG EID of the 2+1 group (2 physical + 1 PG = 3 EIDs)
323	// on the same die as the CLOS 6-port out-of-box group (non-mesh die).
324	int32_t FindPodRemoteEid(const std::vector<UrmaDevice> &urma_devices, int32_t mesh_die_id, std::string &remote_eid) {
325	  int32_t non_mesh_die = 1 - mesh_die_id;
326	  for (const auto &dev : urma_devices) {
327	    if (dev.eid_list.size() != kSecondElementSize + 1) {  // 3 EIDs: 2 physical + 1 PG
328	      continue;
329	    }
330	    std::string pg_eid;
331	    int32_t die_id = -1;
332	    for (const auto &eid : dev.eid_list) {
333	      auto info = ParseEidByte6(eid);
334	      if (info.is_pg_eid) {
335	        pg_eid = eid;
336	        die_id = info.die_id;
337	        break;
338	      }
339	    }
340	    if (pg_eid.empty() || die_id != non_mesh_die) {
341	      continue;
342	    }
343	    remote_eid = pg_eid;
344	    HIXL_LOGI("[FindPodRemoteEid] remote_eid=%s (die_id=%d, 2+1 PG group)", remote_eid.c_str(), die_id);
345	    return SUCCESS;
346	  }
347	  HIXL_LOGE(FAILED, "[FindPodRemoteEid] No 2+1 PG EID found on die %d", non_mesh_die);
348	  return FAILED;
349	}
