386	// Generate a single RouteEntry for one NPU via DSMI + urma_admin + DCMI.
387	// local_eid = the eid corresponding to the UB dev name in urma_admin show.
388	// host_pg_eid (8-port PG) is computed separately for H2U and returned via out param
389	// when npu_id == phy_dev_id.
390	int32_t GenerateRouteEntryForNpu(int32_t npu_id, bool is_server,
391	                                 const std::map<std::string, std::string> &ub_name_to_eid, RouteEntry &entry) {
392	  // Convert phy_dev_id to logic_id for DSMI call
393	  uint32_t logic_id = 0;
394	  const int32_t logic_ret = DcmiProxy::GetLogicIdFromPhyId(static_cast<uint32_t>(npu_id), &logic_id);
395	  HIXL_CHK_BOOL_RET_STATUS(logic_ret == 0, FAILED,
396	                           "[GenerateRouteEntryForNpu] Call api:GetLogicIdFromPhyId failed, ret:%d, npu_id:%d",
397	                           logic_ret, npu_id);
398	
399	  // Get UB dev name from DSMI
400	  std::string ub_dev_name;
401	  int32_t ret = DsmiProxy::GetUbDevName(static_cast<int32_t>(logic_id), ub_dev_name);
402	  if (ret != SUCCESS) {
403	    HIXL_LOGW("[GenerateRouteEntryForNpu] Failed to get UB dev name for npu_id=%d", npu_id);
404	    return ret;
405	  }
406	
407	  // Look up local_eid from urma_admin entries by UB dev name
408	  auto name_it = ub_name_to_eid.find(ub_dev_name);
409	  if (name_it == ub_name_to_eid.end()) {
410	    HIXL_LOGW("[GenerateRouteEntryForNpu] UB dev name '%s' not found in urma_admin show (npu_id=%d)",
411	              ub_dev_name.c_str(), npu_id);
412	    return FAILED;
413	  }
414	
415	  // Get device-side EIDs and find remote_eid
416	  std::vector<UrmaDevice> urma_devices;
417	  ret = GetUrmaDeviceList(npu_id, urma_devices);
418	  if (ret != SUCCESS) {
419	    HIXL_LOGW("[GenerateRouteEntryForNpu] Failed to get urma devices for npu_id=%d", npu_id);
420	    return ret;
421	  }
422	
423	  int32_t mesh_die_id = GetMeshDieId(npu_id, is_server);
424	  std::string remote_eid;
425	  if (is_server) {
426	    ret = FindServerRemoteEid(urma_devices, mesh_die_id, remote_eid);
427	  } else {
428	    ret = FindPodRemoteEid(urma_devices, mesh_die_id, remote_eid);
429	  }
430	  if (ret != SUCCESS) {
431	    HIXL_LOGW("[GenerateRouteEntryForNpu] Failed to find remote_eid for npu_id=%d", npu_id);
432	    return ret;
433	  }
434	
435	  entry.device_id = npu_id;
436	  entry.local_eid = name_it->second;  // PG EID from urma_admin for this UB dev name
437	  entry.remote_eid = remote_eid;
438	  HIXL_LOGI("[GenerateRouteEntryForNpu] npu_id=%d, local_eid=%s, remote_eid=%s", npu_id, entry.local_eid.c_str(),
439	            entry.remote_eid.c_str());
440	  return SUCCESS;
441	}
