443	// Compute Host 8-port PG EID for phy_dev_id using DSMI UB dev name + urma_admin map
444	int32_t ComputeHostPgEid(int32_t phy_dev_id, const std::map<std::string, std::string> &cpu_die_to_pg_eid,
445	                         std::string &host_pg_eid) {
446	  uint32_t logic_id = 0;
447	  const int32_t logic_ret = DcmiProxy::GetLogicIdFromPhyId(static_cast<uint32_t>(phy_dev_id), &logic_id);
448	  HIXL_CHK_BOOL_RET_STATUS(logic_ret == 0, FAILED,
449	                           "[ComputeHostPgEid] Call api:GetLogicIdFromPhyId failed, ret:%d, phy_dev_id:%d", logic_ret,
450	                           phy_dev_id);
451	
452	  std::string ub_dev_name;
453	  int32_t ret = DsmiProxy::GetUbDevName(static_cast<int32_t>(logic_id), ub_dev_name);
454	  if (ret != SUCCESS) {
455	    return ret;
456	  }
457	
458	  std::string cpu_die_key = ExtractCpuDieKey(ub_dev_name);
459	  HIXL_CHK_BOOL_RET_STATUS(!cpu_die_key.empty(), FAILED,
460	                           "[ComputeHostPgEid] Failed to extract cpu_die_key from ub_dev_name:%s", ub_dev_name.c_str());
461	
462	  auto it = cpu_die_to_pg_eid.find(cpu_die_key);
463	  HIXL_CHK_BOOL_RET_STATUS(it != cpu_die_to_pg_eid.end(), FAILED,
464	                           "[ComputeHostPgEid] No 8-port PG EID for cpu_die_key:%s", cpu_die_key.c_str());
465	
466	  host_pg_eid = it->second;
467	  HIXL_LOGI("[ComputeHostPgEid] host_pg_eid=%s (cpu_die_key=%s)", host_pg_eid.c_str(), cpu_die_key.c_str());
468	  return SUCCESS;
469	}
