546	bool ProcfsRouteHandler::ReadFileToString(const std::string &path, std::string &content) {
547	  if (access(path.c_str(), F_OK) != 0) {
548	    HIXL_LOGW("[ReadFileToString] File access check failed: %s, errno=%d(%s)", path.c_str(), errno, strerror(errno));
549	    return false;
550	  }
551	  std::ifstream file(path);
552	  if (!file.is_open()) {
553	    HIXL_LOGW("[ReadFileToString] Failed to open file: %s, errno=%d(%s)", path.c_str(), errno, strerror(errno));
554	    return false;
555	  }
556	  std::ostringstream oss;
557	  oss << file.rdbuf();
558	  content = oss.str();
559	  return true;
560	}
