562	bool ProcfsRouteHandler::WriteStringToFile(const std::string &path, const std::string &content) {
563	  int fd = open(path.c_str(), O_WRONLY);
564	  if (fd < 0) {
565	    HIXL_LOGW("[WriteStringToFile] Failed to open %s: errno=%d(%s)", path.c_str(), errno, strerror(errno));
566	    return false;
567	  }
568	  ssize_t written = write(fd, content.c_str(), content.size());
569	  if (written < 0) {
570	    HIXL_LOGW("[WriteStringToFile] write() failed for %s: errno=%d(%s)", path.c_str(), errno, strerror(errno));
571	  }
572	  close(fd);
573	  fd = -1;
574	  if (written != static_cast<ssize_t>(content.size())) {
575	    HIXL_LOGW("[WriteStringToFile] Incomplete write to %s: written=%zd, expected=%zu", path.c_str(), written,
576	              content.size());
577	    return false;
578	  }
579	  return true;
580	}
