591	bool ProcfsRouteHandler::ParseSlotIdFromLine(const std::string &line, std::string &slot_id) {
592	  if (line.find("dev_id=") == std::string::npos) {
593	    return false;
594	  }
595	  size_t pos = line.find("slot_id=");
596	  if (pos == std::string::npos) {
597	    return false;
