603	bool ProcfsRouteHandler::ParseEidFromLine(const std::string &line, const std::string &prefix, std::string &eid) {
604	  if (line.find(prefix) == std::string::npos) {
605	    return false;
606	  }
607	  size_t pos = line.find(':');
608	  if (pos == std::string::npos) {
609	    return false;
610	  }
611	  eid = TrimString(line.substr(pos + 1));
612	  return !eid.empty();
