614	
615	std::string ProcfsRouteHandler::FormatEidValue(const std::string &eid) {
616	  std::string result = eid;
617	  if (result.size() >= kHexPrefixLength && result[0] == '0' && (result[1] == 'x' || result[1] == 'X')) {
618	    result = result.substr(kHexPrefixLength);
619	  }
620	  // 去掉所有冒号
621	  result.erase(std::remove(result.begin(), result.end(), ':'), result.end());
622	  return result;
623	}
