625	size_t ProcfsRouteHandler::SelectEidIndexByNpuId(int32_t npu_id, size_t local_count, size_t remote_count) {
626	  int32_t group_offset = npu_id % 8;
627	  size_t eid_idx = (group_offset < 4) ? 0 : 1;  // 前4个用第一组，后4个用第二组
628	  if (eid_idx >= local_count || eid_idx >= remote_count) {
629	    HIXL_LOGW("[ParsePairInfo] npu_id=%d: eid_idx=%zu out of range (local=%zu, remote=%zu), fallback to index 0",
630	              npu_id, eid_idx, local_count, remote_count);
631	    eid_idx = 0;
632	  }
633	  return eid_idx;
634	}
635	
636	bool ProcfsRouteHandler::CollectEidsFromPairInfo(const std::string &pair_info_content, std::string &found_slot_id,
637	                                                 std::vector<std::string> &local_eids,
638	                                                 std::vector<std::string> &remote_eids) {
639	  std::istringstream iss(pair_info_content);
640	  std::string line;
641	  while (std::getline(iss, line)) {
642	    line = TrimString(line);
643	    if (line.empty()) {
644	      continue;
645	    }
646	    std::string slot;
647	    if (ParseSlotIdFromLine(line, slot)) {
648	      found_slot_id = slot;
649	    }
650	    std::string eid_val;
651	    if (ParseEidFromLine(line, "local_eid", eid_val)) {
652	      local_eids.push_back(eid_val);
653	    }
654	    if (ParseEidFromLine(line, "remote_eid", eid_val)) {
655	      remote_eids.push_back(eid_val);
656	    }
657	  }
658	  return (!found_slot_id.empty() && !local_eids.empty() && !remote_eids.empty());
659	}
660	
661	bool ProcfsRouteHandler::ParsePairInfoForDevice(const std::string &pair_info_content, int32_t npu_id, int32_t &slot_id,
662	                                                std::string &local_eid, std::string &remote_eid) const {
663	  std::string found_slot_id;
664	  std::vector<std::string> local_eids;
665	  std::vector<std::string> remote_eids;
666	
667	  if (!CollectEidsFromPairInfo(pair_info_content, found_slot_id, local_eids, remote_eids)) {
668	    HIXL_LOGW("[ParsePairInfo] npu_id=%d: failed to collect slot_id or eids", npu_id);
669	    return false;
670	  }
671	
672	  HIXL_LOGD("[ParsePairInfo] npu_id=%d, slot_id=[%s], local_eids_count=%zu, remote_eids_count=%zu", npu_id,
673	            found_slot_id.c_str(), local_eids.size(), remote_eids.size());
674	
675	  size_t eid_idx = SelectEidIndexByNpuId(npu_id, local_eids.size(), remote_eids.size());
676	
677	  try {
678	    slot_id = std::stoi(found_slot_id);
679	  } catch (const std::exception &) {
680	    slot_id = npu_id;
681	  }
682	
683	  local_eid = FormatEidValue(local_eids[eid_idx]);
684	  remote_eid = FormatEidValue(remote_eids[eid_idx]);
685	
686	  return (!local_eid.empty() || !remote_eid.empty());
687	}
