689	int32_t ProcfsRouteHandler::ProcessNpuProcfsRoute(int32_t npu_id, const std::string &dev_id_path,
690	                                                  const std::string &pair_info_path, RouteEntry &entry) const {
691	  HIXL_LOGI("[Procfs] Processing npu_id=%d", npu_id);
692	  // 写入phyid选择设备
693	  std::ostringstream dev_id_ss;
694	  dev_id_ss << npu_id << "\n";
695	  if (!WriteStringToFile(dev_id_path, dev_id_ss.str())) {
696	    HIXL_LOGW("[Procfs] Failed to write npu_id=%d to %s", npu_id, dev_id_path.c_str());
697	    return FAILED;
698	  }
699	
700	  // 短暂延时确保内核更新
701	  usleep(kProcfsWriteDelayUs);
702	
703	  // 读取 pair_info
704	  std::string pair_info_content;
705	  if (!ReadFileToString(pair_info_path, pair_info_content)) {
706	    HIXL_LOGW("[Procfs] Failed to read pair_info for npu_id=%d", npu_id);
707	    return FAILED;
708	  }
709	
710	  // 解析 pair_info
711	  int32_t slot_id = npu_id;
712	  std::string local_eid;
713	  std::string remote_eid;
714	  if (!ParsePairInfoForDevice(pair_info_content, npu_id, slot_id, local_eid, remote_eid)) {
715	    HIXL_LOGW("[Procfs] Failed to parse pair_info for npu_id=%d", npu_id);
716	    return FAILED;
717	  }
718	
719	  HIXL_LOGI("[Procfs] Parsed: npu_id=%d, slot_id=%d, local_eid=[%s], remote_eid=[%s]", npu_id, slot_id,
720	            local_eid.c_str(), remote_eid.c_str());
721	
722	  // 只生成 H2D 方向的 RouteEntry
723	  entry.device_id = npu_id;
724	  entry.local_eid = local_eid;
725	  entry.remote_eid = remote_eid;
726	  return SUCCESS;
727	}
