729	int32_t ProcfsRouteHandler::GenerateRouteData(const std::set<int32_t> &related_npu_ids, RouteData &route_data) const {
730	  route_data.entries.clear();
731	
732	  std::string proc_base = FindProcBasePath();
733	  HIXL_CHK_BOOL_RET_STATUS(!proc_base.empty(), FAILED, "Neither /proc/ascend_ub nor /proc/asdrv_ub found");
734	  HIXL_LOGI("Using procfs base path: %s", proc_base.c_str());
735	
736	  std::string dev_id_path = proc_base + "/" + kProcDevIdFile;
737	  std::string pair_info_path = proc_base + "/" + kProcPairInfoFile;
738	
739	  for (int32_t npu_id : related_npu_ids) {
740	    RouteEntry entry;
741	    int32_t ret = ProcessNpuProcfsRoute(npu_id, dev_id_path, pair_info_path, entry);
742	    if (ret == SUCCESS) {
743	      route_data.entries.push_back(entry);
744	      HIXL_LOGI("[Procfs] RouteEntry H2D: npu_id=%d, device_id=%d, local_eid=[%s], remote_eid=[%s]", npu_id,
745	                entry.device_id, entry.local_eid.c_str(), entry.remote_eid.c_str());
746	    }
747	  }
748	
749	  HIXL_CHK_BOOL_RET_STATUS(!route_data.entries.empty(), FAILED, "No route entries generated from procfs");
750	
751	  HIXL_LOGI("[Procfs] Generated %zu route entries from procfs:", route_data.entries.size());
752	  for (size_t i = 0; i < route_data.entries.size(); ++i) {
753	    const auto &entry = route_data.entries[i];
754	    HIXL_LOGI("[Procfs]   [%zu] device_id=%d, local_eid=[%s], remote_eid=[%s]", i, entry.device_id,
755	              entry.local_eid.c_str(), entry.remote_eid.c_str());
756	  }
757	
758	  return SUCCESS;
759	}
