767	bool LoadRouteKvMap(std::ifstream &file, std::map<std::string, std::string> &kv_map) {
768	  std::string line;
769	  while (std::getline(file, line)) {
770	    size_t eq_pos = line.find('=');
771	    if (eq_pos == std::string::npos) {
772	      continue;
773	    }
774	
775	    std::string key = line.substr(0, eq_pos);
776	    std::string value = line.substr(eq_pos + 1);
777	
778	    size_t key_end = key.find_last_not_of(" \t\r\n");
779	    if (key_end != std::string::npos) {
780	      key = key.substr(0, key_end + 1);
781	    }
782	
783	    size_t val_start = value.find_first_not_of(" \t\r\n");
784	    size_t val_end = value.find_last_not_of(" \t\r\n");
785	    if (val_start != std::string::npos && val_end != std::string::npos) {
786	      value = value.substr(val_start, val_end - val_start + 1);
787	    }
788	    kv_map[key] = value;
789	  }
790	  return true;
791	}
