793	void AddRouteEntriesForDevice(const std::map<std::string, std::string> &kv_map, int32_t device_idx, int32_t device_id,
794	                              RouteData &route_data) {
795	  std::string chan_num_key = "pair" + std::to_string(device_idx) + "_chan_num";
796	  int32_t chan_num = 1;
797	  auto chan_num_it = kv_map.find(chan_num_key);
798	  if (chan_num_it != kv_map.end()) {
799	    try {
800	      chan_num = std::stoi(chan_num_it->second);
801	    } catch (const std::exception &) {
802	      chan_num = 1;
803	    }
804	  }
805	
806	  for (int32_t j = 0; j < chan_num; ++j) {
807	    std::string local_key = "pair" + std::to_string(device_idx) + "_chan" + std::to_string(j) + "_local_eid";
808	    std::string remote_key = "pair" + std::to_string(device_idx) + "_chan" + std::to_string(j) + "_remote_eid";
809	
810	    auto local_it = kv_map.find(local_key);
811	    auto remote_it = kv_map.find(remote_key);
812	    if (local_it != kv_map.end() && remote_it != kv_map.end()) {
813	      RouteEntry entry;
814	      entry.device_id = device_id;
815	      entry.local_eid = local_it->second;
816	      entry.remote_eid = remote_it->second;
817	      // 去掉 "0x" 前缀
818	      if (entry.local_eid.size() >= kHexPrefixLength && entry.local_eid[0] == '0' && entry.local_eid[1] == 'x') {
819	        entry.local_eid = entry.local_eid.substr(kHexPrefixLength);
820	      }
821	      if (entry.remote_eid.size() >= kHexPrefixLength && entry.remote_eid[0] == '0' && entry.remote_eid[1] == 'x') {
822	        entry.remote_eid = entry.remote_eid.substr(kHexPrefixLength);
823	      }
824	      route_data.entries.push_back(entry);
825	    }
826	  }
827	}
