829	int32_t BuildRouteEntries(const std::map<std::string, std::string> &kv_map, RouteData &route_data) {
830	  auto it = kv_map.find("pair_device_num");
831	  HIXL_CHK_BOOL_RET_STATUS(it != kv_map.end(), FAILED, "Missing pair_device_num");
832	
833	  int32_t pair_device_num = 0;
834	  try {
835	    pair_device_num = std::stoi(it->second);
836	  } catch (const std::exception &) {
837	    HIXL_LOGE(FAILED, "Invalid pair_device_num value: %s", it->second.c_str());
838	    return FAILED;
839	  }
840	  for (int32_t i = 0; i < pair_device_num; ++i) {
841	    std::string dev_id_key = "pair" + std::to_string(i) + "_dev_id";
842	    auto dev_it = kv_map.find(dev_id_key);
843	    if (dev_it == kv_map.end()) {
844	      continue;
845	    }
846	
847	    int32_t device_id = 0;
848	    try {
849	      device_id = std::stoi(dev_it->second);
850	    } catch (const std::exception &) {
851	      HIXL_LOGW("Invalid dev_id value: %s", dev_it->second.c_str());
852	      continue;
853	    }
854	    AddRouteEntriesForDevice(kv_map, i, device_id, route_data);
855	  }
856	
857	  HIXL_LOGI("Parsed %zu route entries", route_data.entries.size());
858	  for (size_t i = 0; i < route_data.entries.size(); ++i) {
859	    const auto &entry = route_data.entries[i];
860	    HIXL_LOGI("  route_entry[%zu]: device_id=%d, local_eid=[%s], remote_eid=[%s]", i, entry.device_id,
861	              entry.local_eid.c_str(), entry.remote_eid.c_str());
862	  }
863	  return SUCCESS;
864	}
