902	static bool ParsePortsFromJson(const nlohmann::json &edge, const char *key, std::vector<std::string> &ports) {
903	  if (!edge.contains(key) || !edge[key].is_array()) {
904	    return false;
905	  }
906	  for (const auto &port : edge[key]) {
907	    if (port.is_string()) {
908	      ports.push_back(port.get<std::string>());
909	    }
910	  }
911	  return true;
