914	static int32_t ParseSingleLink(const nlohmann::json &edge, TopoLink &link) {
915	  if (!edge.contains("net_layer")) {
916	    HIXL_LOGW("Missing net_layer in edge object, skipping");
917	    return 1;  // 1 表示跳过
918	  }
919	  link.net_layer = edge.value("net_layer", 0);
920	  link.link_type = edge.value("link_type", "");
921	  link.topo_type = edge.value("topo_type", "");
922	  link.local_a = edge.value("local_a", 0);
923	  link.local_b = edge.value("local_b", 0);
924	  link.remote_a = edge.value("remote_a", -1);
925	  link.remote_b = edge.value("remote_b", -1);
926	
927	  ParsePortsFromJson(edge, "local_a_ports", link.local_a_ports);
928	  ParsePortsFromJson(edge, "local_b_ports", link.local_b_ports);
929	  return 0;  // 0 表示成功
930	}
931	
932	static int32_t ParseTopoJson(const std::string &topo_path, nlohmann::json &j) {
933	  if (access(topo_path.c_str(), F_OK) != 0) {
934	    HIXL_LOGE(PARAM_INVALID, "Topo file access failed: %s, errno=%d(%s)", topo_path.c_str(), errno, strerror(errno));
935	    return PARAM_INVALID;
936	  }
937	  std::ifstream file(topo_path);
938	  if (!file.is_open()) {
939	    HIXL_LOGE(PARAM_INVALID, "Failed to open topo file: %s, errno=%d(%s)", topo_path.c_str(), errno, strerror(errno));
940	    return PARAM_INVALID;
941	  }
942	
943	  try {
944	    file >> j;
945	  } catch (const nlohmann::json::exception &e) {
946	    HIXL_LOGE(FAILED, "Failed to parse topo file JSON: %s", e.what());
947	    return FAILED;
948	  }
949	  file.close();
950	
951	  HIXL_CHK_BOOL_RET_STATUS(j.contains("edge_list") && j["edge_list"].is_array() && !j["edge_list"].empty(), FAILED,
952	                           "No or empty edge_list found in path:%s", topo_path.c_str());
953	  return SUCCESS;
954	}
955	
956	int32_t ParseTopoFile(const std::string &topo_path, TopoData &topo_data) {
957	  topo_data.links.clear();
958	
959	  nlohmann::json j;
960	  int32_t ret = ParseTopoJson(topo_path, j);
961	  if (ret != SUCCESS) {
962	    return ret;
963	  }
964	
965	  for (const auto &edge : j["edge_list"]) {
966	    TopoLink link;
967	    link.remote_a = -1;
968	    link.remote_b = -1;
969	
970	    if (ParseSingleLink(edge, link) == 1) {
971	      continue;  // 跳过该 edge
972	    }
973	    topo_data.links.push_back(link);
974	  }
975	
976	  HIXL_LOGI("Parsed %zu links from %s", topo_data.links.size(), topo_path.c_str());
977	  return SUCCESS;
978	}
