983	    HIXL_LOGW("Route file %s does not exist, will auto-generate route data via procfs fallback, errno=%d(%s)",
984	              route_path.c_str(), errno, strerror(errno));
985	    return PARAM_INVALID;
986	  }
987	  std::ifstream file(route_path);
988	  if (!file.is_open()) {
989	    HIXL_CHK_BOOL_RET_STATUS(false, PARAM_INVALID, "Failed to open route file: %s, errno=%d(%s)", route_path.c_str(),
