1002	bool ShouldSkipD2DLink(const TopoLink &link, std::array<size_t, 4> &skip_reason) {  // 4: skip reason categories
1003	  if (link.net_layer != 0) {
1004	    ++skip_reason[0];
1005	    return true;
1006	  }
1007	  if (link.link_type != kLinkTypePeer2Peer) {
1008	    ++skip_reason[1];
1009	    return true;
1010	  }
1011	  if (link.topo_type != kTopoType1DMesh) {
1012	    ++skip_reason[2];
1013	    return true;
1014	  }
1015	  return false;
1016	}
