1018	void AddD2DEdgesFromLink(const D2DEdgeMatchInput &input, std::vector<EndpointConfig> &edges,
1019	                         size_t &no_port_match_local, size_t &no_port_match_peer) {
1020	  for (size_t i = 0; i < input.local_ports.size() && i < input.peer_ports.size(); ++i) {
1021	    const std::string &local_port = input.local_ports[i];
1022	    const std::string &peer_port = input.peer_ports[i];
1023	
1024	    auto local_eid_it = input.self_rootinfo.port_to_eid.find(local_port);
1025	    if (local_eid_it == input.self_rootinfo.port_to_eid.end()) {
1026	      ++no_port_match_local;
1027	      HIXL_LOGD("No EID for local port '%s'", local_port.c_str());
1028	      continue;
1029	    }
1030	    const std::string &comm_id = local_eid_it->second;
1031	
1032	    auto peer_eid_it = input.peer_rootinfo.port_to_eid.find(peer_port);
1033	    if (peer_eid_it == input.peer_rootinfo.port_to_eid.end()) {
1034	      ++no_port_match_peer;
1035	      HIXL_LOGD("No EID for peer port '%s' on npu_id=%d", peer_port.c_str(), input.peer_id);
1036	      continue;
1037	    }
1038	    const std::string &dst_eid = peer_eid_it->second;
1039	
1040	    EndpointConfig edge{};
1041	    edge.protocol = kProtocolUbCtp;
1042	    edge.comm_id = comm_id;
1043	    edge.placement = kPlacementDevice;
1044	    edge.dst_eid = dst_eid;
1045	    edges.push_back(edge);
1046	    HIXL_LOGD("D2D matched: comm_id=%s, dst_eid=%s", comm_id.c_str(), dst_eid.c_str());
1047	  }
1048	}
