1050	int32_t GenerateD2DEdges(const TopoData &topo_data, const std::map<int32_t, NpuRootInfo> &npu_rootinfos, int32_t phy_id,
1051	                         std::vector<EndpointConfig> &edges) {
1052	  edges.clear();
1053	
1054	  auto self_it = npu_rootinfos.find(phy_id);
1055	  if (self_it == npu_rootinfos.end()) {
1056	    HIXL_LOGW("No rootinfo for self npu_id=%d", phy_id);
1057	    return SUCCESS;
1058	  }
1059	  const auto &self_rootinfo = self_it->second;
1060	
1061	  HIXL_LOGI("D2D: phy_id=%d, topo_links=%zu, self_rootinfo_size=%zu", phy_id, topo_data.links.size(),
1062	            self_rootinfo.port_to_eid.size());
1063	
1064	  std::array<size_t, 4> skip_reason = {0, 0, 0, 0};  // 4: skip reason categories for D2D links
1065	  size_t no_rootinfo_peer = 0;
1066	  size_t no_port_match_local = 0;
1067	  size_t no_port_match_peer = 0;
1068	
1069	  for (const auto &link : topo_data.links) {
1070	    if (ShouldSkipD2DLink(link, skip_reason)) {
1071	      continue;
1072	    }
1073	
1074	    bool is_local_a_side = (link.local_a == phy_id);
1075	    bool is_local_b_side = (link.local_b == phy_id);
1076	    if (!is_local_a_side && !is_local_b_side) {
1077	      ++skip_reason[3];
1078	      continue;
1079	    }
1080	
1081	    int32_t peer_id = is_local_a_side ? link.local_b : link.local_a;
1082	    const std::vector<std::string> &local_ports = is_local_a_side ? link.local_a_ports : link.local_b_ports;
1083	    const std::vector<std::string> &peer_ports = is_local_a_side ? link.local_b_ports : link.local_a_ports;
1084	
1085	    if (local_ports.empty() || peer_ports.empty()) {
1086	      HIXL_LOGD("D2D skip (empty ports)");
1087	      continue;
1088	    }
1089	
1090	    auto peer_it = npu_rootinfos.find(peer_id);
1091	    if (peer_it == npu_rootinfos.end()) {
1092	      ++no_rootinfo_peer;
1093	      HIXL_LOGD("D2D No rootinfo for peer npu_id=%d", peer_id);
1094	      continue;
1095	    }
1096	    const auto &peer_rootinfo = peer_it->second;
1097	
1098	    AddD2DEdgesFromLink({self_rootinfo, peer_rootinfo, peer_id, local_ports, peer_ports}, edges, no_port_match_local,
1099	                        no_port_match_peer);
1100	  }
1101	
1102	  HIXL_LOGI(
1103	      "D2D result: matched=%zu, skip(net_layer)=%zu, skip(link_type)=%zu, "
1104	      "skip(topo_type)=%zu, skip(phy_id)=%zu, no_port_match_local=%zu, "
1105	      "no_port_match_peer=%zu, no_rootinfo_peer=%zu",
1106	      edges.size(), skip_reason[0], skip_reason[1], skip_reason[2], skip_reason[3], no_port_match_local,
1107	      no_port_match_peer, no_rootinfo_peer);
1108	  return SUCCESS;
1109	}
