1344	// Generate route data via DSMI (UB dev name) + urma_admin + DCMI (device EID)
1345	// Replaces the old route.conf + procfs fallback approach.
1346	// local_eid = PG EID from urma_admin matching the UB dev name (for H2D/D2H)
1347	// host_pg_eid = 8-port PG EID (for H2U), computed from cpu_die_key
1348	int32_t GenerateRouteDataViaDsmi(int32_t phy_dev_id, bool is_server, RouteGenResult &result) {
1349	  result.related_npu_ids = CollectRelatedNpuIds(phy_dev_id);
1350	  result.route_data.entries.clear();
1351	  result.host_pg_eid.clear();
1352	
1353	  // Execute urma_admin show once
